19|/// Hash of tool call arguments — args never leave the server.
20|#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
21|pub struct ArgsHash(pub String);
22|
23|impl ArgsHash {
24|    /// Compute SHA-256 hash of serialized arguments.
25|    pub fn from_args(args: &serde_json::Value) -> Self {
26|        let mut hasher = Sha256::new();
27|        hasher.update(args.to_string().as_bytes());
28|        let hash = hex::encode(hasher.finalize());
29|        Self(hash[..32].to_string())
30|    }
