114|/// In-memory approval store with CAS-based atomic claiming.
115|/// Production would use SQL with lease-based durability (Task 7C.1.2).
116|pub struct ApprovalStore {
117|    approvals: Arc<RwLock<HashMap<ApprovalId, ApprovalRequest>>>,
118|    config: ApprovalConfig,
119|}
120|
121|impl ApprovalStore {
122|    pub fn new(config: ApprovalConfig) -> Self {
123|        Self {
124|            approvals: Arc::new(RwLock::new(HashMap::new())),
125|            config,
126|        }
127|    }
128|
129|    /// Create a new approval request. Returns the request with server-generated ID.
130|    pub fn create_request(
131|        &self,
132|        summary: String,
133|        tool_name: String,
134|        args: serde_json::Value,
135|        thread_id: String,
136|        tool_call_id: String,
137|    ) -> ApprovalRequest {
138|        let id = Uuid::new_v4().to_string();
139|        let args_hash = ArgsHash::from_args(&args);
140|        let headless_excluded = self
141|            .config
142|            .headless_excluded_tools
143|            .contains(&tool_name);
144|        let expires_at = Utc::now() + self.config.default_ttl;
145|
146|        let request = ApprovalRequest {
147|            id: id.clone(),
148|            summary,
149|            tool_name,
150|            args_hash,
151|            thread_id,
152|            tool_call_id,
153|            expires_at,
154|            status: ApprovalStatus::Pending,
155|            headless_excluded,
156|            args,
157|        };
158|
159|        let mut store = self.approvals.write().unwrap();
160|        store.insert(id, request.clone());
161|        request
162|    }
163|
164|    /// Attempt to approve a request. Uses CAS semantics:
165|    /// only succeeds if current status is Pending and not expired.
166|    /// Returns Err if already decided or expired.
167|    pub fn approve(
168|        &self,
169|        approval_id: &str,
170|        approved_by: &str,
171|    ) -> Result<ApprovalRequest, ApprovalError> {
172|        let mut store = self.approvals.write().unwrap();
173|        let request = store
174|            .get_mut(approval_id)
175|            .ok_or(ApprovalError::NotFound)?;
176|
177|        // Check expiry first
178|        if Utc::now() > request.expires_at {
179|            request.status = ApprovalStatus::Expired;
180|            return Err(ApprovalError::Expired);
181|        }
182|
183|        // CAS: only transition from Pending
184|        match &request.status {
185|            ApprovalStatus::Pending => {
186|                request.status = ApprovalStatus::Approved {
187|                    approved_by: approved_by.to_string(),
188|                    approved_at: Utc::now(),
189|                };
190|                Ok(request.clone())
191|            }
192|            ApprovalStatus::Approved { .. } => Err(ApprovalError::AlreadyDecided),
193|            ApprovalStatus::Declined { .. } => Err(ApprovalError::AlreadyDecided),
194|            ApprovalStatus::Expired => Err(ApprovalError::Expired),
195|        }
196|    }
197|
198|    /// Attempt to decline a request. Same CAS semantics as approve.
199|    pub fn decline(
200|        &self,
201|        approval_id: &str,
202|        declined_by: &str,
203|        reason: Option<String>,
204|    ) -> Result<ApprovalRequest, ApprovalError> {
205|        let mut store = self.approvals.write().unwrap();
206|        let request = store
207|            .get_mut(approval_id)
208|            .ok_or(ApprovalError::NotFound)?;
209|
210|        if Utc::now() > request.expires_at {
211|            request.status = ApprovalStatus::Expired;
212|            return Err(ApprovalError::Expired);
213|        }
214|
215|        match &request.status {
216|            ApprovalStatus::Pending => {
217|                request.status = ApprovalStatus::Declined {
218|                    declined_by: declined_by.to_string(),
219|                    declined_at: Utc::now(),
220|                    reason,
221|                };
222|                Ok(request.clone())
223|            }
224|            _ => Err(ApprovalError::AlreadyDecided),
225|        }
226|    }
