228|    /// Get a client-safe view of an approval (no raw args).
229|    /// Also checks TTL and updates status to Expired if needed.
230|    pub fn get_client_view(&self, approval_id: &str) -> Option<ApprovalClientView> {
231|        let mut store = self.approvals.write().unwrap();
232|        let request = store.get_mut(approval_id)?;
233|
234|        // Auto-expire on read
235|        if matches!(request.status, ApprovalStatus::Pending) && Utc::now() > request.expires_at {
236|            request.status = ApprovalStatus::Expired;
237|        }
238|
239|        Some(ApprovalClientView {
240|            id: request.id.clone(),
241|            summary: mask_secrets(&request.summary, &self.config.secret_fields),
242|            tool_name: request.tool_name.clone(),
243|            args_hash: request.args_hash.clone(),
244|            thread_id: request.thread_id.clone(),
245|            tool_call_id: request.tool_call_id.clone(),
246|            expires_at: request.expires_at,
247|            status: request.status.clone(),
248|            headless_excluded: request.headless_excluded,
249|        })
250|    }
