252|    /// Get the full server-side request (includes raw args).
253|    /// Used internally for tool execution after approval.
254|    pub fn get_server_request(&self, approval_id: &str) -> Option<ApprovalRequest> {
255|        let store = self.approvals.read().unwrap();
256|        store.get(approval_id).cloned()
257|    }
258|
259|    /// Idempotent result recovery: if already decided, return the cached decision.
260|    /// Used when client re-renders or retries.
261|    pub fn recover_decision(
262|        &self,
263|        approval_id: &str,
264|    ) -> Result<Option<ApprovalClientView>, ApprovalError> {
265|        let store = self.approvals.read().unwrap();
266|        let request = store
267|            .get(approval_id)
268|            .ok_or(ApprovalError::NotFound)?;
269|
270|        match &request.status {
271|            ApprovalStatus::Pending => Ok(None), // Still waiting
272|            _ => {
273|                // Already decided — return cached view
274|                drop(store);
275|                Ok(self.get_client_view(approval_id))
276|            }
277|        }
278|    }
279|
280|    /// Filter tools for headless contexts: exclude approval-gated tools.
281|    pub fn filter_for_headless(&self, tool_names: &[String]) -> Vec<String> {
282|        tool_names
283|            .iter()
284|            .filter(|name| !self.config.headless_excluded_tools.contains(name))
285|            .cloned()
286|            .collect()
287|    }
288|
289|    /// Number of pending approvals.
290|    pub fn pending_count(&self) -> usize {
291|        let store = self.approvals.read().unwrap();
292|        store
293|            .values()
294|            .filter(|r| matches!(r.status, ApprovalStatus::Pending))
295|            .count()
296|    }
