324|/// Mask secret field values in a summary string.
325|/// Replaces patterns like `password=abc123` with `password=[MASKED]`.
326|fn mask_secrets(text: &str, secret_fields: &[String]) -> String {
327|    let mut result = text.to_string();
328|    for field in secret_fields {
329|        // Match field=value patterns (case-insensitive field name)
330|        let lower = result.to_lowercase();
331|        let field_lower = field.to_lowercase();
332|        let mut search_from = 0;
333|
334|        while let Some(pos) = lower[search_from..].find(&field_lower) {
335|            let abs_pos = search_from + pos;
336|            let after_field = abs_pos + field_lower.len();
337|
338|            // Check for = sign after field name
339|            if after_field < result.len() && result.as_bytes()[after_field] == b'=' {
340|                let value_start = after_field + 1;
341|                let remaining = &result[value_start..];
342|                let value_end = remaining
343|                    .find(|c: char| c == ' ' || c == '&' || c == '\n' || c == '"' || c == ',')
344|                    .unwrap_or(remaining.len());
345|
346|                if value_end > 0 {
347|                    let replacement = format!("{}=[MASKED]", &result[abs_pos..after_field]);
348|                    result.replace_range(abs_pos..value_start + value_end, &replacement);
349|                    // Advance past the replacement
350|                    search_from = abs_pos + replacement.len();
351|                    // Re-lowercase since we modified the string
352|                    let lower_new = result.to_lowercase();
353|                    // Continue searching in the updated lowercase version
354|                    if search_from >= result.len() {
355|                        break;
356|                    }
357|                    // Use the updated lowercase for next iteration
358|                    let _ = lower_new; // suppress unused warning
359|                    continue;
360|                }
361|            }
362|            search_from = abs_pos + field_lower.len();
363|        }
364|    }
365|    result
