1|//! Task Durability via SQL Leases (Task 7C.1.2)
2|//!
3|//! Server-side task queue with SQL-based leasing for single-owner execution,
4|//! state machine transitions, maintenance recovery, exponential backoff,
5|//! and circuit breaker. Database is the sole source of time — zero Date::now()
6|//! in lease logic.
7|//!
8|//! Sources: OpenMuse `engine/service.ts`, OpenDuet `work/queue.ts`.
9|
10|use chrono::{DateTime, Utc};
11|use rusqlite::{params, Connection, OptionalExtension};
12|use serde::{Deserialize, Serialize};
13|use std::sync::{Arc, Mutex};
14|use std::time::Duration;
15|use uuid::Uuid;
16|
17|/// Unique identifier for a durable task.
18|pub type TaskId = String;
19|
20|/// Unique identifier for a lease holder.
21|pub type LeaseId = String;
22|
23|/// Task state machine: queued → running → waiting_approval/waiting_input → succeeded/failed/cancelled.
24|#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
25|pub enum TaskState {
26|    Queued,
27|    Running,
28|    WaitingApproval,
29|    WaitingInput,
30|    Succeeded,
31|    Failed,
32|    Cancelled,
33|}
34|
35|impl TaskState {
36|    /// Whether this state is terminal (no further transitions allowed).
37|    pub fn is_terminal(&self) -> bool {
38|        matches!(
39|            self,
40|            TaskState::Succeeded | TaskState::Failed | TaskState::Cancelled
41|        )
42|    }
