44|    /// Parse from string stored in SQLite.
45|    pub fn from_db(s: &str) -> Option<Self> {
46|        match s {
47|            "queued" => Some(TaskState::Queued),
48|            "running" => Some(TaskState::Running),
49|            "waiting_approval" => Some(TaskState::WaitingApproval),
50|            "waiting_input" => Some(TaskState::WaitingInput),
51|            "succeeded" => Some(TaskState::Succeeded),
52|            "failed" => Some(TaskState::Failed),
53|            "cancelled" => Some(TaskState::Cancelled),
54|            _ => None,
55|        }
