134|/// SQL-backed task store with lease-based durability.
135|pub struct TaskStore {
136|    conn: Arc<Mutex<Connection>>,
137|    config: TaskWorkerConfig,
138|}
139|
140|impl TaskStore {
141|    /// Create a new TaskStore with an in-memory SQLite database.
142|    /// Production would use a file path or connection pool.
143|    pub fn new_in_memory(config: TaskWorkerConfig) -> Result<Self, TaskError> {
144|        let conn = Connection::open_in_memory()?;
145|        Self::init_schema(&conn)?;
146|        Ok(Self {
147|            conn: Arc::new(Mutex::new(conn)),
148|            config,
149|        })
150|    }
151|
152|    /// Create a new TaskStore backed by a file.
153|    pub fn new_file(path: &str, config: TaskWorkerConfig) -> Result<Self, TaskError> {
154|        let conn = Connection::open(path)?;
155|        conn.execute_batch("PRAGMA journal_mode=WAL;")?;
156|        Self::init_schema(&conn)?;
157|        Ok(Self {
158|            conn: Arc::new(Mutex::new(conn)),
159|            config,
160|        })
161|    }
162|
163|    fn init_schema(conn: &Connection) -> Result<(), rusqlite::Error> {
164|        conn.execute_batch(
165|            "CREATE TABLE IF NOT EXISTS durable_tasks (
166|                id TEXT PRIMARY KEY,
167|                payload TEXT NOT NULL,
168|                state TEXT NOT NULL DEFAULT 'queued',
169|                lease_id TEXT,
170|                lease_until TEXT,
171|                consecutive_failures INTEGER NOT NULL DEFAULT 0,
172|                next_retry_at TEXT,
173|                created_at TEXT NOT NULL,
174|                updated_at TEXT NOT NULL
175|            );
176|            CREATE INDEX IF NOT EXISTS idx_tasks_state ON durable_tasks(state);
177|            CREATE INDEX IF NOT EXISTS idx_tasks_lease ON durable_tasks(lease_until);
178|            CREATE INDEX IF NOT EXISTS idx_tasks_retry ON durable_tasks(next_retry_at);",
179|        )
180|    }
181|
182|    /// Enqueue a new task. Returns the generated task ID.
183|    pub fn enqueue(&self, payload: String) -> Result<TaskId, TaskError> {
184|        let id = Uuid::new_v4().to_string();
185|        let now = Utc::now();
186|        let conn = self.conn.lock().unwrap();
187|        conn.execute(
188|            "INSERT INTO durable_tasks (id, payload, state, consecutive_failures, created_at, updated_at)
189|             VALUES (?1, ?2, 'queued', 0, ?3, ?3)",
190|            params![id, payload, now.to_rfc3339()],
191|        )?;
192|        Ok(id)
193|    }
194|
195|    /// Attempt to claim a queued or retryable task using CAS.
196|    /// Database-as-clock: uses SQL datetime comparison, never Date::now().
197|    /// Returns the claimed task or None if nothing available.
198|    pub fn try_claim(&self, worker_id: &str) -> Result<Option<DurableTask>, TaskError> {
199|        let lease_id = Uuid::new_v4().to_string();
200|        let now = Utc::now();
201|        let lease_until = now + chrono::Duration::from_std(self.config.lease_duration)
202|            .map_err(|e| TaskError::Database(e.to_string()))?;
203|
204|        let conn = self.conn.lock().unwrap();
205|
206|        // CAS: atomically claim one task that is either:
207|        // 1. queued with no lease
208|        // 2. lease expired (stale)
209|        // 3. retryable (next_retry_at <= now) and not circuit-broken
210|        let rows_changed = conn.execute(
211|            "UPDATE durable_tasks SET
212|                lease_id = ?1,
213|                lease_until = ?2,
214|                state = 'running',
215|                updated_at = ?3
216|             WHERE id = (
217|                SELECT id FROM durable_tasks
218|                WHERE (state = 'queued' AND lease_id IS NULL)
219|                   OR (state IN ('waiting_approval','waiting_input') AND lease_id IS NULL)
220|                   OR (state = 'running' AND lease_until < ?3)
221|                   OR (state IN ('queued','failed') AND next_retry_at IS NOT NULL AND next_retry_at <= ?3 AND consecutive_failures < ?4)
222|                ORDER BY created_at ASC
223|                LIMIT 1
224|             )",
225|            params![lease_id, lease_until.to_rfc3339(), now.to_rfc3339(), self.config.max_consecutive_failures],
226|        )?;
227|
228|        if rows_changed == 0 {
229|            return Ok(None);
230|        }
231|
232|        // Fetch the claimed task
233|        let task = conn
234|            .query_row(
235|                "SELECT id, payload, state, lease_id, lease_until, consecutive_failures, next_retry_at, created_at, updated_at
236|                 FROM durable_tasks WHERE lease_id = ?1",
237|                params![lease_id],
238|                |row| {
239|                    Ok(DurableTask {
240|                        id: row.get(0)?,
241|                        payload: row.get(1)?,
242|                        state: TaskState::from_db(&row.get::<_, String>(2)?).unwrap_or(TaskState::Queued),
243|                        lease_id: row.get(3)?,
244|                        lease_until: row.get::<_, Option<String>>(4)?.and_then(|s| DateTime::parse_from_rfc3339(&s).ok().map(|d| d.with_timezone(&Utc))),
245|                        consecutive_failures: row.get(5)?,
246|                        next_retry_at: row.get::<_, Option<String>>(6)?.and_then(|s| DateTime::parse_from_rfc3339(&s).ok().map(|d| d.with_timezone(&Utc))),
247|                        created_at: DateTime::parse_from_rfc3339(&row.get::<_, String>(7)?).unwrap().with_timezone(&Utc),
248|                        updated_at: DateTime::parse_from_rfc3339(&row.get::<_, String>(8)?).unwrap().with_timezone(&Utc),
249|                    })
250|                },
251|            )
252|            .optional()?;
253|
254|        Ok(task)
255|    }
256|
257|    /// Transition task state with validation. Only the current lease holder can transition.
258|    pub fn transition(
259|        &self,
260|        task_id: &str,
261|        lease_id: &str,
262|        new_state: TaskState,
263|    ) -> Result<(), TaskError> {
264|        let conn = self.conn.lock().unwrap();
265|        let now = Utc::now();
266|
267|        // Validate transition
268|        let current_state_str: String = conn
269|            .query_row(
270|                "SELECT state FROM durable_tasks WHERE id = ?1 AND lease_id = ?2",
271|                params![task_id, lease_id],
272|                |row| row.get(0),
273|            )
274|            .optional()?
275|            .ok_or(TaskError::NotFound)?;
276|
277|        let current_state =
278|            TaskState::from_db(&current_state_str).ok_or(TaskError::Database(format!(
279|                "unknown state: {}",
280|                current_state_str
281|            )))?;
282|
283|        if !Self::is_valid_transition(&current_state, &new_state) {
284|            return Err(TaskError::InvalidTransition {
285|                from: current_state.to_db().to_string(),
286|                to: new_state.to_db().to_string(),
287|            });
288|        }
289|
290|        let lease_clear = new_state.is_terminal() || matches!(new_state, TaskState::WaitingApproval | TaskState::WaitingInput);
291|
292|        if lease_clear {
293|            conn.execute(
294|                "UPDATE durable_tasks SET state = ?1, lease_id = NULL, lease_until = NULL, updated_at = ?2 WHERE id = ?3 AND lease_id = ?4",
295|                params![new_state.to_db(), now.to_rfc3339(), task_id, lease_id],
296|            )?;
297|        } else {
298|            conn.execute(
299|                "UPDATE durable_tasks SET state = ?1, updated_at = ?2 WHERE id = ?3 AND lease_id = ?4",
300|                params![new_state.to_db(), now.to_rfc3339(), task_id, lease_id],
301|            )?;
302|        }
303|
304|        let _next_retry: Option<DateTime<Utc>> = None; // reserved for future use
305|        Ok(())
306|    }
307|
308|    /// Record a failure with exponential backoff and circuit breaker check.
309|    pub fn record_failure(&self, task_id: &str, lease_id: &str) -> Result<(), TaskError> {
310|        let conn = self.conn.lock().unwrap();
311|        let now = Utc::now();
312|
313|        // Increment failures and compute backoff atomically
314|        conn.execute(
315|            "UPDATE durable_tasks SET
316|                consecutive_failures = consecutive_failures + 1,
317|                state = CASE WHEN consecutive_failures + 1 >= ?1 THEN 'failed' ELSE 'queued' END,
318|                next_retry_at = CASE WHEN consecutive_failures + 1 < ?1 THEN ?2 ELSE NULL END,
319|                lease_id = NULL,
320|                lease_until = NULL,
321|                updated_at = ?3
322|             WHERE id = ?4 AND lease_id = ?5",
323|            params![
324|                self.config.max_consecutive_failures,
325|                Self::compute_next_retry(now, 0, &self.config).to_rfc3339(),
326|                now.to_rfc3339(),
327|                task_id,
328|                lease_id,
329|            ],
330|        )?;
331|
332|        // Check if circuit breaker tripped
333|        let failures: u32 = conn
334|            .query_row(
335|                "SELECT consecutive_failures FROM durable_tasks WHERE id = ?1",
336|                params![task_id],
337|                |row| row.get(0),
338|            )
339|            .optional()?
340|            .unwrap_or(0);
341|
342|        if failures >= self.config.max_consecutive_failures {
343|            return Err(TaskError::CircuitBreakerOpen { failures });
344|        }
345|
346|        Ok(())
347|    }
348|
349|    /// Compute exponential backoff: base * 2^failures, capped at max_backoff.
350|    fn compute_next_retry(now: DateTime<Utc>, failures: u32, config: &TaskWorkerConfig) -> DateTime<Utc> {
351|        let backoff_secs = config.backoff_base_secs.saturating_mul(2u64.saturating_pow(failures));
352|        let backoff = Duration::from_secs(backoff_secs).min(config.max_backoff);
353|        now + chrono::Duration::from_std(backoff).unwrap_or(chrono::Duration::hours(1))
354|    }
355|
356|    /// Maintenance loop: recover tasks with expired leases.
357|    /// Returns number of recovered tasks.
358|    pub fn run_maintenance(&self) -> Result<u32, TaskError> {
359|        let conn = self.conn.lock().unwrap();
360|        let now = Utc::now();
361|
362|        // Reset stale running tasks back to queued
363|        let recovered = conn.execute(
364|            "UPDATE durable_tasks SET
365|                state = 'queued',
366|                lease_id = NULL,
367|                lease_until = NULL,
368|                updated_at = ?1
369|             WHERE state = 'running' AND lease_until < ?1",
370|            params![now.to_rfc3339()],
371|        )?;
372|
373|        Ok(recovered as u32)
374|    }
375|
376|    /// Manual circuit breaker reset. Requires explicit human action.
377|    pub fn reset_circuit_breaker(&self, task_id: &str) -> Result<(), TaskError> {
378|        let conn = self.conn.lock().unwrap();
379|        let now = Utc::now();
380|
381|        let rows = conn.execute(
382|            "UPDATE durable_tasks SET
383|                consecutive_failures = 0,
384|                next_retry_at = NULL,
385|                state = 'queued',
386|                updated_at = ?1
387|             WHERE id = ?2 AND consecutive_failures >= ?3",
388|            params![now.to_rfc3339(), task_id, self.config.max_consecutive_failures],
389|        )?;
390|
391|        if rows == 0 {
392|            return Err(TaskError::NotFound);
393|        }
394|        Ok(())
395|    }
396|
397|    /// Get task by ID.
398|    pub fn get_task(&self, task_id: &str) -> Result<Option<DurableTask>, TaskError> {
399|        let conn = self.conn.lock().unwrap();
400|        conn.query_row(
401|            "SELECT id, payload, state, lease_id, lease_until, consecutive_failures, next_retry_at, created_at, updated_at
402|             FROM durable_tasks WHERE id = ?1",
403|            params![task_id],
404|            |row| {
405|                Ok(DurableTask {
406|                    id: row.get(0)?,
407|                    payload: row.get(1)?,
408|                    state: TaskState::from_db(&row.get::<_, String>(2)?).unwrap_or(TaskState::Queued),
409|                    lease_id: row.get(3)?,
410|                    lease_until: row.get::<_, Option<String>>(4)?.and_then(|s| DateTime::parse_from_rfc3339(&s).ok().map(|d| d.with_timezone(&Utc))),
411|                    consecutive_failures: row.get(5)?,
412|                    next_retry_at: row.get::<_, Option<String>>(6)?.and_then(|s| DateTime::parse_from_rfc3339(&s).ok().map(|d| d.with_timezone(&Utc))),
413|                    created_at: DateTime::parse_from_rfc3339(&row.get::<_, String>(7)?).unwrap().with_timezone(&Utc),
414|                    updated_at: DateTime::parse_from_rfc3339(&row.get::<_, String>(8)?).unwrap().with_timezone(&Utc),
415|                })
416|            },
417|        )
418|        .optional()
419|        .map_err(TaskError::from)
420|    }
421|
422|    /// Count tasks by state.
423|    pub fn count_by_state(&self, state: TaskState) -> Result<u32, TaskError> {
424|        let conn = self.conn.lock().unwrap();
425|        let count: u32 = conn.query_row(
426|            "SELECT COUNT(*) FROM durable_tasks WHERE state = ?1",
427|            params![state.to_db()],
428|            |row| row.get(0),
429|        )?;
430|        Ok(count)
431|    }
432|
433|    /// Check if a state transition is valid.
434|    fn is_valid_transition(from: &TaskState, to: &TaskState) -> bool {
435|        matches!(
436|            (from, to),
437|            (TaskState::Queued, TaskState::Running)
438|                | (TaskState::Running, TaskState::Succeeded)
439|                | (TaskState::Running, TaskState::Failed)
440|                | (TaskState::Running, TaskState::Cancelled)
441|                | (TaskState::Running, TaskState::WaitingApproval)
442|                | (TaskState::Running, TaskState::WaitingInput)
443|                | (TaskState::WaitingApproval, TaskState::Running)
444|                | (TaskState::WaitingInput, TaskState::Running)
445|                | (TaskState::WaitingApproval, TaskState::Cancelled)
446|                | (TaskState::WaitingInput, TaskState::Cancelled)
447|        )
448|    }
449|}
