1|//! Outcome Uncertainty Tri-State (Task 7C.1.3)
2|//!
3|//! Three-valued outcome classification for write operations where network
4|//! errors or 5xx responses make success/failure indeterminate. OutcomeUnknown
5|//! forces human confirmation rather than auto-retry. Includes audit logging
6|//! and notification deduplication.
7|//!
8|//! Source: OpenMuse `google.ts:20` (OutcomeUnknownError)
9|
10|use chrono::{DateTime, Utc};
11|use serde::{Deserialize, Serialize};
12|use sha2::{Digest, Sha256};
13|use std::collections::VecDeque;
14|use std::sync::{Arc, Mutex};
15|
16|/// Three-valued outcome for write operations.
17|#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
18|pub enum Outcome {
19|    /// Write confirmed successful (2xx response).
20|    Succeeded,
21|    /// Write confirmed failed (4xx, validation error, explicit rejection).
22|    Failed,
23|    /// Write outcome indeterminate (network error, 5xx, timeout).
24|    /// Requires human confirmation before proceeding — never auto-retried.
25|    OutcomeUnknown,
26|}
27|
28|impl Outcome {
29|    /// Whether this outcome requires human intervention.
30|    pub fn requires_human_confirmation(&self) -> bool {
31|        matches!(self, Outcome::OutcomeUnknown)
32|    }
33|
34|    /// Whether this outcome is terminal (no retry needed).
35|    pub fn is_terminal(&self) -> bool {
36|        matches!(self, Outcome::Succeeded | Outcome::Failed)
37|    }
38|
39|    /// Serialize to string for storage/logging.
40|    pub fn to_db(&self) -> &'static str {
41|        match self {
42|            Outcome::Succeeded => "succeeded",
43|            Outcome::Failed => "failed",
44|            Outcome::OutcomeUnknown => "outcome_unknown",
45|        }
46|    }
47|
48|    /// Parse from string.
49|    pub fn from_db(s: &str) -> Option<Self> {
50|        match s {
51|            "succeeded" => Some(Outcome::Succeeded),
52|            "failed" => Some(Outcome::Failed),
53|            "outcome_unknown" => Some(Outcome::OutcomeUnknown),
54|            _ => None,
55|        }
56|    }
57|}
