59|/// Classification of HTTP/write errors into Outcome tri-state.
60|#[derive(Debug, Clone)]
61|pub struct OutcomeClassifier;
62|
63|impl OutcomeClassifier {
64|    /// Classify an HTTP status code into an Outcome.
65|    /// - 2xx → Succeeded
66|    /// - 4xx → Failed (client error, deterministic)
67|    /// - 5xx → OutcomeUnknown (server error, may have succeeded)
68|    /// - Other → OutcomeUnknown
69|    pub fn from_status(status: u16) -> Outcome {
70|        match status {
71|            200..=299 => Outcome::Succeeded,
72|            400..=499 => Outcome::Failed,
73|            500..=599 => Outcome::OutcomeUnknown,
74|            _ => Outcome::OutcomeUnknown,
75|        }
76|    }
77|
78|    /// Classify a network/IO error as OutcomeUnknown.
79|    /// Network errors mean the write may or may not have reached the server.
80|    pub fn from_network_error() -> Outcome {
81|        Outcome::OutcomeUnknown
82|    }
83|
84|    /// Classify a timeout as OutcomeUnknown.
85|    /// Timeout means the server may have processed the request.
86|    pub fn from_timeout() -> Outcome {
87|        Outcome::OutcomeUnknown
88|    }
89|
90|    /// Classify from a Result where Err = network/IO error.
91|    pub fn from_result<T, E>(result: &Result<T, E>) -> Outcome {
92|        match result {
93|            Ok(_) => Outcome::Succeeded,
94|            Err(_) => Outcome::OutcomeUnknown,
95|        }
96|    }
97|}
