99|/// A single audit entry recording an outcome transition.
100|#[derive(Debug, Clone, Serialize, Deserialize)]
101|pub struct OutcomeAuditEntry {
102|    pub timestamp: DateTime<Utc>,
103|    pub operation_id: String,
104|    pub previous_outcome: Option<String>,
105|    pub new_outcome: String,
106|    pub reason: String,
107|    pub actor: String,
108|}
109|
110|/// Audit log for outcome transitions. Ring buffer with configurable capacity.
111|pub struct OutcomeAuditLog {
112|    entries: Arc<Mutex<VecDeque<OutcomeAuditEntry>>>,
113|    capacity: usize,
114|}
115|
116|impl OutcomeAuditLog {
117|    pub fn new(capacity: usize) -> Self {
118|        Self {
119|            entries: Arc::new(Mutex::new(VecDeque::with_capacity(capacity))),
120|            capacity,
121|        }
122|    }
123|
124|    /// Record an outcome transition.
125|    pub fn record(
126|        &self,
127|        operation_id: &str,
128|        previous: Option<&Outcome>,
129|        new: &Outcome,
130|        reason: &str,
131|        actor: &str,
132|    ) {
133|        let entry = OutcomeAuditEntry {
134|            timestamp: Utc::now(),
135|            operation_id: operation_id.to_string(),
136|            previous_outcome: previous.map(|o| o.to_db().to_string()),
137|            new_outcome: new.to_db().to_string(),
138|            reason: reason.to_string(),
139|            actor: actor.to_string(),
140|        };
141|
142|        let mut entries = self.entries.lock().unwrap();
143|        if entries.len() >= self.capacity {
144|            entries.pop_front();
145|        }
146|        entries.push_back(entry);
147|    }
148|
149|    /// Get all entries (oldest first).
150|    pub fn entries(&self) -> Vec<OutcomeAuditEntry> {
151|        self.entries.lock().unwrap().iter().cloned().collect()
152|    }
153|
154|    /// Get entries for a specific operation.
155|    pub fn entries_for_operation(&self, operation_id: &str) -> Vec<OutcomeAuditEntry> {
156|        self.entries
157|            .lock()
158|            .unwrap()
159|            .iter()
160|            .filter(|e| e.operation_id == operation_id)
161|            .cloned()
162|            .collect()
163|    }
164|
165|    /// Count entries.
166|    pub fn len(&self) -> usize {
167|        self.entries.lock().unwrap().len()
168|    }
169|
170|    /// Check if empty.
171|    pub fn is_empty(&self) -> bool {
172|        self.entries.lock().unwrap().is_empty()
173|    }
174|}
