176|/// Notification deduplication key generator.
177|/// Prevents duplicate alerts for the same logical operation across retries.
178|pub struct NotificationDedup;
179|
180|impl NotificationDedup {
181|    /// Generate a dedup key from operation components.
182|    /// Same logical operation → same key → suppress duplicate notifications.
183|    pub fn compute_key(operation_type: &str, target: &str, payload_hash: &[u8]) -> String {
184|        let mut hasher = Sha256::new();
185|        hasher.update(operation_type.as_bytes());
186|        hasher.update(b":");
187|        hasher.update(target.as_bytes());
188|        hasher.update(b":");
189|        hasher.update(payload_hash);
190|        hex::encode(hasher.finalize())
191|    }
192|
193|    /// Generate a dedup key from a simple operation descriptor.
194|    pub fn compute_key_simple(operation_type: &str, target: &str) -> String {
195|        let mut hasher = Sha256::new();
196|        hasher.update(operation_type.as_bytes());
197|        hasher.update(b":");
198|        hasher.update(target.as_bytes());
199|        hex::encode(hasher.finalize())
200|    }
201|}
202|
203|/// Tracks seen dedup keys to suppress duplicate notifications.
204|pub struct NotificationTracker {
205|    seen: Arc<Mutex<std::collections::HashSet<String>>>,
206|    max_entries: usize,
207|}
208|
209|impl NotificationTracker {
210|    pub fn new(max_entries: usize) -> Self {
211|        Self {
212|            seen: Arc::new(Mutex::new(std::collections::HashSet::new())),
213|            max_entries,
214|        }
215|    }
216|
217|    /// Check if a notification should be sent. Returns true if new (not seen).
218|    /// Marks the key as seen if returning true.
219|    pub fn should_notify(&self, dedup_key: &str) -> bool {
220|        let mut seen = self.seen.lock().unwrap();
221|        if seen.contains(dedup_key) {
222|            false
223|        } else {
224|            // Evict oldest entries if at capacity (simple strategy: clear half)
225|            if seen.len() >= self.max_entries {
226|                let to_remove: Vec<_> = seen.iter().take(self.max_entries / 2).cloned().collect();
227|                for key in to_remove {
228|                    seen.remove(&key);
229|                }
230|            }
231|            seen.insert(dedup_key.to_string());
232|            true
233|        }
234|    }
235|
236|    /// Reset tracking (e.g., after manual acknowledgment).
237|    pub fn reset(&self) {
238|        self.seen.lock().unwrap().clear();
239|    }
240|
241|    /// Number of tracked keys.
242|    pub fn tracked_count(&self) -> usize {
243|        self.seen.lock().unwrap().len()
244|    }
245|}
