247|/// Retry policy for outcomes. OutcomeUnknown never auto-retries.
248|pub struct OutcomeRetryPolicy;
249|
250|impl OutcomeRetryPolicy {
251|    /// Determine if an outcome should be auto-retried.
252|    /// Only Failed outcomes are eligible for auto-retry.
253|    /// OutcomeUnknown ALWAYS requires human confirmation.
254|    pub fn should_auto_retry(outcome: &Outcome) -> bool {
255|        match outcome {
256|            Outcome::Succeeded => false, // No retry needed
257|            Outcome::Failed => true,     // Deterministic failure, safe to retry
258|            Outcome::OutcomeUnknown => false, // NEVER auto-retry unknown outcomes
259|        }
260|    }
261|
262|    /// Get the recommended action for an outcome.
263|    pub fn recommended_action(outcome: &Outcome) -> &'static str {
264|        match outcome {
265|            Outcome::Succeeded => "none",
266|            Outcome::Failed => "auto_retry",
267|            Outcome::OutcomeUnknown => "human_confirmation_required",
268|        }
269|    }
270|}
